#include <stdint.h>
#include "stm32f469xx.h"

/* HSI frequency = 16000000 Hz (anh cho, chưa có tài liệu) */
uint32_t SystemCoreClock = 16000000UL;

/* Linker symbols */
extern uint32_t _estack;
extern uint32_t _sidata;
extern uint32_t _sdata;
extern uint32_t _edata;
extern uint32_t _sbss;
extern uint32_t _ebss;

extern int main(void);

void Reset_Handler(void);
void Default_Handler(void);

void NMI_Handler(void)        __attribute__((weak, alias("Default_Handler")));
void HardFault_Handler(void)  __attribute__((weak, alias("Default_Handler")));
void MemManage_Handler(void)  __attribute__((weak, alias("Default_Handler")));
void BusFault_Handler(void)   __attribute__((weak, alias("Default_Handler")));
void UsageFault_Handler(void) __attribute__((weak, alias("Default_Handler")));
void SVC_Handler(void)        __attribute__((weak, alias("Default_Handler")));
void DebugMon_Handler(void)   __attribute__((weak, alias("Default_Handler")));
void PendSV_Handler(void)     __attribute__((weak, alias("Default_Handler")));
void SysTick_Handler(void)    __attribute__((weak, alias("Default_Handler")));

__attribute__((section(".isr_vector"), used))
void (* const g_pfnVectors[])(void) = {
    (void (*)(void))((uint32_t)&_estack),
    Reset_Handler,
    NMI_Handler,
    HardFault_Handler,
    MemManage_Handler,
    BusFault_Handler,
    UsageFault_Handler,
    0, 0, 0, 0,
    SVC_Handler,
    DebugMon_Handler,
    0,
    PendSV_Handler,
    SysTick_Handler,
};

void Reset_Handler(void)
{
    /* Enable FPU coprocessors CP10 and CP11 (full access) */
    SCB_CPACR |= ((3UL << 20) | (3UL << 22));

    /* Copy initialized data from Flash to RAM */
    uint32_t *pSrc = &_sidata;
    uint32_t *pDest = &_sdata;
    while (pDest < &_edata) {
        *pDest++ = *pSrc++;
    }

    /* Zero fill the bss section */
    uint32_t *pBss = &_sbss;
    while (pBss < &_ebss) {
        *pBss++ = 0;
    }

    /* Call the application entry point */
    main();

    /* Trap if main returns */
    while (1);
}

void Default_Handler(void)
{
    while (1);
}

#include <stdint.h>
#include "stm32f469xx.h"
#include "FreeRTOS.h"
#include "task.h"

/* Initialize onboard LEDs: PG6 (LED1), PD4 (LED2), PD5 (LED3), PK3 (LED4) */
static void prvSetupHardware(void)
{
    /* Enable GPIO clocks */
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN;

    /* Configure PG6 as General purpose output mode (01) */
    GPIOG->MODER &= ~(3UL << (LED1_PIN * 2));
    GPIOG->MODER |= (1UL << (LED1_PIN * 2));
    /* LEDs are active LOW: turn off initially by setting bit in BSRR */
    GPIOG->BSRR = (1UL << LED1_PIN);

    /* Configure PD4 and PD5 as General purpose output mode (01) */
    GPIOD->MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
    GPIOD->MODER |= ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
    GPIOD->BSRR = (1UL << LED2_PIN) | (1UL << LED3_PIN);

    /* Configure PK3 as General purpose output mode (01) */
    GPIOK->MODER &= ~(3UL << (LED4_PIN * 2));
    GPIOK->MODER |= (1UL << (LED4_PIN * 2));
    GPIOK->BSRR = (1UL << LED4_PIN);
}

/* LED Blink Task: Toggles LED1 (PG6) every 500 ms */
static void vBlinkTask(void *pvParameters)
{
    (void)pvParameters;
    for (;;) {
        /* Turn ON LED1 (Active LOW: reset pin via high half of BSRR) */
        GPIOG->BSRR = (1UL << (LED1_PIN + 16));
        vTaskDelay(pdMS_TO_TICKS(500));

        /* Turn OFF LED1 (set pin via low half of BSRR) */
        GPIOG->BSRR = (1UL << LED1_PIN);
        vTaskDelay(pdMS_TO_TICKS(500));
    }
}

int main(void)
{
    prvSetupHardware();

    /* Create the LED blink task */
    xTaskCreate(
        vBlinkTask,
        "Blink",
        configMINIMAL_STACK_SIZE,
        0,
        tskIDLE_PRIORITY + 1,
        0
    );

    /* Start the scheduler */
    vTaskStartScheduler();

    /* Should never reach here */
    for (;;);
    return 0;
}

