def lay_ke_hoach_hien_tai(db_path: str = ".eide/store.sqlite") -> Optional[Dict[str, Any]]:
    # Thử nhiều đường dẫn khả dĩ
    candidates = [
        Path(db_path),
        Path.cwd() / ".eide" / "store.sqlite",
        Path(__file__).resolve().parent.parent / "store.sqlite",
        Path(__file__).resolve().parent.parent.parent / ".eide" / "store.sqlite"
    ]
    for p in candidates:
        if p.exists():
            try:
                conn = sqlite3.connect(p)
                cursor = conn.cursor()
                cursor.execute("SELECT canonical_json, summary FROM artefacts WHERE id = 'plan:current'")
                row = cursor.fetchone()
                conn.close()
                if row and row[0]:
                    data = json.loads(row[0])
                    if isinstance(data, dict):
                        return data
            except Exception:
                continue
    return None

