"""

from __future__ import annotations

import json
from pathlib import Path
import sqlite3
from typing import Any, Dict, List, Optional


def tim_tep_store_sqlite(db_path: Optional[str] = None) -> Optional[Path]:
    if db_path:
        p = Path(db_path)
        if p.is_file():
            return p

    candidates: List[Path] = [
        Path(".eide/store.sqlite"),
        Path.cwd() / ".eide" / "store.sqlite",
    ]

    # Duyệt ngược lên từ cwd
    cur = Path.cwd()
    for _ in range(5):
        cand = cur / ".eide" / "store.sqlite"
        if cand.is_file():
            candidates.append(cand)
        cur = cur.parent

    # Duyệt ngược lên từ __file__
    cur = Path(__file__).resolve().parent
    for _ in range(6):
        cand = cur / ".eide" / "store.sqlite"
        if cand.is_file():
            candidates.append(cand)
        cur = cur.parent

    for p in candidates:
        if p.is_file():
            return p
    return None


def lay_ke_hoach_hien_tai(db_path: Optional[str] = None) -> Optional[Dict[str, Any]]:
    target = tim_tep_store_sqlite(db_path)
    if not target:
        return None

    try:
        conn = sqlite3.connect(target)
        cursor = conn.cursor()

        # Tìm các bảng trong cơ sở dữ liệu
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table'")
        tables = [r[0] for r in cursor.fetchall() if not r[0].startswith("sqlite_")]

        found_json: Optional[str] = None

        for tbl in tables:
            cursor.execute(f"PRAGMA table_info({tbl})")
            cols = [info[1] for info in cursor.fetchall()]
            id_col = next((c for c in cols if c in ("id", "ma", "key", "artefact_id")), None)
            if not id_col:
                continue

            try:
                cursor.execute(f"SELECT * FROM {tbl} WHERE {id_col} = 'plan:current'")
                rows = cursor.fetchall()
                if rows:
                    row = rows[0]
                    # Tìm cột chứa chuỗi JSON có chứa 'steps' hoặc 'muc_tieu'
                    for col_idx, col_name in enumerate(cols):
                        val = row[col_idx]
                        if isinstance(val, (bytes, bytearray)):
                            val = val.decode("utf-8", errors="ignore")
                        if isinstance(val, str) and ("steps" in val or "muc_tieu" in val):
                            found_json = val
                            break
                    if found_json:
                        break
            except Exception:
                continue

        conn.close()

        if found_json:
            data = json.loads(found_json)
            if isinstance(data, dict):
                # Trường hợp lưu bao bọc canonical
                if "canonical" in data and isinstance(data["canonical"], dict):
                    return data["canonical"]
                return data
    except Exception:
        return None

    return None


