    int in_x = (x >= 200 && x <= 600);
    int in_y = ((y >= 350 && y <= 475) || (y >= 5 && y <= 130));
    int in_swap = (y >= 200 && y <= 600) && ((x >= 350 && x <= 475) || (x >= 5 && x <= 130));

    if ((in_x && in_y) || in_swap) {
        UI_ToggleScreen();
        return 1;
    }
    return 0;
}

/**
